static unsigned int round34_loader_read_u16(const unsigned char **cursor)
{
	unsigned int value = (*cursor)[0] | ((unsigned int)(*cursor)[1] << 8);

	*cursor += 2;
	return value;
}

static int round34_loader_decode_frame(volatile unsigned short *pixels,
				       const unsigned char *cursor,
				       const unsigned char *end)
{
	unsigned int command;
	unsigned int count;
	unsigned int index;
	unsigned int kind;
	unsigned int position = 0;
	unsigned short value;

	while (cursor < end) {
		if ((unsigned long)(end - cursor) < 2)
			return -1;
		command = round34_loader_read_u16(&cursor);
		kind = command >> 14;
		count = (command & 0x3fff) + 1;
		if (count > FB_XRES * FB_YRES - position)
			return -1;
		if (kind == 0) {
			position += count;
		} else if (kind == 1) {
			if ((unsigned long)(end - cursor) < 2)
				return -1;
			value = (unsigned short)round34_loader_read_u16(&cursor);
			for (index = 0; index < count; index++)
				pixels[position++] = value;
		} else if (kind == 2) {
			if ((unsigned long)(end - cursor) < count * 2)
				return -1;
			for (index = 0; index < count; index++)
				pixels[position++] =
					(unsigned short)round34_loader_read_u16(&cursor);
		} else {
			return -1;
		}
	}
	return position == FB_XRES * FB_YRES ? 0 : -1;
}

static int framebuffer_formal_loader(void)
{
	struct fb_var_screeninfo pan;
	volatile unsigned short *mapping_pixels;
	volatile unsigned short *pixels;
	volatile unsigned short *previous;
	const unsigned char *start;
	const unsigned char *end;
	void *mapping;
	unsigned int frame;
	unsigned int page;
	int fd;
	int result = -1;

	fd = open("/dev/fb0", O_RDWR, 0);
	if (fd < 0)
		return -1;
	mapping = round27_mmap(0, FB_MEMORY_BYTES, PROT_READ | PROT_WRITE,
			       MAP_SHARED, fd, 0);
	if (mapping == MAP_FAILED)
		goto out_close;
	mapping_pixels = (volatile unsigned short *)mapping;
	memset((void *)mapping_pixels, 0, FB_MEMORY_BYTES);
	memset(&pan, 0, sizeof(pan));
	if (ioctl(fd, FBIOGET_VSCREENINFO, &pan) < 0)
		goto out_unmap;

	for (frame = 0; frame < ROUND34_LOADER_FRAME_COUNT; frame++) {
		page = frame & 1;
		pixels = mapping_pixels + page * FB_XRES * FB_YRES;
		if (frame) {
			previous = mapping_pixels + (page ^ 1) * FB_XRES * FB_YRES;
			memcpy((void *)pixels, (const void *)previous, FB_FRAME_BYTES);
		}
		start = round34_loader_data + round34_loader_offsets[frame];
		end = round34_loader_data + round34_loader_offsets[frame + 1];
		if (round34_loader_decode_frame(pixels, start, end) < 0)
			goto out_unmap;
		__sync_synchronize();
		pan.xoffset = 0;
		pan.yoffset = page * FB_YRES;
		pan.activate = FB_ACTIVATE_VBL;
		if (ioctl(fd, FBIOPAN_DISPLAY, &pan) < 0)
			goto out_unmap;
		(void)msleep(ROUND34_LOADER_FRAME_MILLISECONDS);
	}
	result = 0;

out_unmap:
	(void)munmap(mapping, FB_MEMORY_BYTES);
out_close:
	(void)close(fd);
	if (result == 0)
		report("GKD Round34: formal loader animation rendered\n");
	else
		report("GKD Round34: formal loader animation failed\n");
	return result;
}

static int round39_framebuffer_ready;

#define GKD_ROUND39_MAX_ANIMATION_CYCLES 2U

static long round38_fd_read(void *context, unsigned char *buffer,
			    unsigned long count)
{
	int fd = (int)(long)context;

	return (long)read(fd, buffer, count);
}

static int round38_read_exact(int fd, void *buffer, unsigned long count)
{
	return gkd_round38_read_exact(round38_fd_read, (void *)(long)fd,
				       (unsigned char *)buffer, count);
}

static unsigned int round39_frame_hash(volatile unsigned short *pixels)
{
	volatile unsigned char *bytes = (volatile unsigned char *)pixels;
	unsigned int hash = 2166136261U;
	unsigned int index;

	for (index = 0; index < FB_FRAME_BYTES; ++index) {
		hash ^= bytes[index];
		hash *= 16777619U;
	}
	return hash;
}

static int round39_userspace_owns_framebuffer(
	int framebuffer_fd, volatile unsigned short *mapping_pixels,
	unsigned int expected_yoffset, const unsigned int expected_hash[2])
{
	struct fb_var_screeninfo current;
	unsigned int page;

	memset(&current, 0, sizeof(current));
	if (ioctl(framebuffer_fd, FBIOGET_VSCREENINFO, &current) < 0)
		return 1;
	if (current.yoffset != expected_yoffset)
		return 1;
	for (page = 0; page < 2; ++page)
		if (round39_frame_hash(mapping_pixels +
				page * FB_XRES * FB_YRES) != expected_hash[page])
			return 1;
	return 0;
}

static int framebuffer_external_loop(const char *path)
{
	struct fb_var_screeninfo pan;
	volatile unsigned short *mapping_pixels;
	volatile unsigned short *pixels;
	unsigned char header[GKD_ROUND38_HEADER_BYTES];
	unsigned int expected_hash[2];
	unsigned int expected_yoffset;
	off_t file_bytes;
	void *mapping = MAP_FAILED;
	unsigned int cycle;
	unsigned int frame;
	unsigned int page;
	pid_t animation_pid;
	int child = 0;
	int animation_fd = -1;
	int framebuffer_fd = -1;
	int result = -1;

	animation_fd = open(path, O_RDONLY, 0);
	if (animation_fd < 0)
		goto out;
	file_bytes = lseek(animation_fd, 0, SEEK_END);
	if (file_bytes != (off_t)GKD_ROUND38_TOTAL_BYTES ||
	    lseek(animation_fd, 0, SEEK_SET) != 0)
		goto out;
	if (round38_read_exact(animation_fd, header,
				GKD_ROUND38_HEADER_BYTES) < 0 ||
	    !gkd_round38_header_valid(header, (unsigned long)file_bytes))
		goto out;

	framebuffer_fd = open("/dev/fb0", O_RDWR, 0);
	if (framebuffer_fd < 0)
		goto out;
	mapping = round27_mmap(0, FB_MEMORY_BYTES, PROT_READ | PROT_WRITE,
			       MAP_SHARED, framebuffer_fd, 0);
	if (mapping == MAP_FAILED)
		goto out;
	mapping_pixels = (volatile unsigned short *)mapping;
	memset(&pan, 0, sizeof(pan));
	if (ioctl(framebuffer_fd, FBIOGET_VSCREENINFO, &pan) < 0)
		goto out;
	expected_hash[0] = round39_frame_hash(mapping_pixels);
	expected_hash[1] = round39_frame_hash(mapping_pixels +
		FB_XRES * FB_YRES);
	expected_yoffset = pan.yoffset;

	animation_pid = fork();
	if (animation_pid < 0)
		goto out;
	if (animation_pid > 0) {
		result = 0;
		goto out;
	}
	child = 1;
	report("GKD Round39: bounded startup animation child started\n");

	for (cycle = 0; cycle < GKD_ROUND39_MAX_ANIMATION_CYCLES; ++cycle) {
		if (lseek(animation_fd, GKD_ROUND38_HEADER_BYTES, SEEK_SET) !=
		    (off_t)GKD_ROUND38_HEADER_BYTES)
			goto out;
		for (frame = 0; frame < GKD_ROUND38_FRAME_COUNT; frame++) {
			page = frame & 1;
			pixels = mapping_pixels + page * FB_XRES * FB_YRES;
			if (round38_read_exact(animation_fd, (void *)pixels,
						GKD_ROUND38_FRAME_BYTES) < 0)
				goto out;
			__sync_synchronize();
			expected_hash[page] = round39_frame_hash(pixels);
			pan.xoffset = 0;
			pan.yoffset = page * FB_YRES;
			pan.activate = FB_ACTIVATE_VBL;
			if (ioctl(framebuffer_fd, FBIOPAN_DISPLAY, &pan) < 0)
				goto out;
			expected_yoffset = pan.yoffset;
			(void)msleep(GKD_ROUND38_FRAME_MILLISECONDS);
			if (round39_userspace_owns_framebuffer(framebuffer_fd,
					mapping_pixels, expected_yoffset,
					expected_hash)) {
				report("GKD Round39: userspace framebuffer handoff detected\n");
				result = 0;
				goto out;
			}
		}
	}
	report("GKD Round39: bounded startup animation window completed\n");
	result = 0;

out:
	if (mapping != MAP_FAILED)
		(void)munmap(mapping, FB_MEMORY_BYTES);
	if (framebuffer_fd >= 0)
		(void)close(framebuffer_fd);
	if (animation_fd >= 0)
		(void)close(animation_fd);
	if (child) {
		if (result < 0)
			report("GKD Round39: bounded startup animation child failed\n");
		exit(result == 0 ? 0 : 1);
	}
	if (result == 0)
		report("GKD Round39: bounded startup animation launched\n");
	return result;
}

#include "round64-request-gate.h"
static int r80i_return_tick(void);
static int r80i_trace(const char marker[4]);
#define R80M_RETURN_TICK() r80i_return_tick()
#define R80M_TRACE(marker) r80i_trace(marker)
#include "round83-maintenance-loader.generated.h"
#include "round83-ram-payload.generated.h"

enum r80i_state {
	R80I_SM,
	R80I_QUIESCING,
	R80I_DEBUG,
	R80I_RESTORING,
	R80I_REBOOT_REQUIRED,
};

#define R80I_AF_UNIX 1
#define R80I_SOCK_SEQPACKET 5
#define R80I_SOL_SOCKET 0xffff
#define R80I_SO_PEERCRED 18
#define R80I_LISTEN_BACKLOG 4
#define R80I_F_SETFD 2
#define R80I_F_SETFL 4
#define R80I_FD_CLOEXEC 1
#define R80I_KERNEL_SLOT_OFFSET ((off_t)0x900000)
#define R80I_KERNEL_SLOT_BYTES 0x600000UL
#define R80I_SYSTEM_EXIT_STEPS 300U
#define R80I_TRACE_SECTOR 0x9f83
#define R80I_TRACE_OFFSET ((off_t)R80I_TRACE_SECTOR * 512)
#define R80I_LOOP_CLR_FD 0x4c01
#define R80I_LOOP_GET_STATUS64 0x4c05
#define R80I_LOOP_SCAN_MAX 16U

struct r80i_loop_info64 {
	unsigned long long device;
	unsigned long long inode;
	unsigned long long rdevice;
	unsigned long long offset;
	unsigned long long sizelimit;
	unsigned int number;
	unsigned int encrypt_type;
	unsigned int encrypt_key_size;
	unsigned int flags;
	unsigned char file_name[64];
	unsigned char crypt_name[64];
	unsigned char encrypt_key[32];
	unsigned long long init[2];
};
typedef char r80i_loop_info64_size_must_be_232[
	sizeof(struct r80i_loop_info64) == 232U ? 1 : -1];

struct r80i_sockaddr_un {
	unsigned short family;
	char path[108];
};

struct r80i_peercred {
	int pid;
	unsigned int uid;
	unsigned int gid;
};

static const char r80i_socket_name[] = "gkdmini-supervisor-v1";
static int r80i_listener = -1;
static enum r80i_state r80i_state = R80I_REBOOT_REQUIRED;
static unsigned char r80i_kernel_before[R64M_SHA256_BYTES];
static int r80i_kernel_before_valid;
static int r80i_returning;

static int r80i_socket(int domain, int type, int protocol)
{
	return (int)my_syscall3(__NR_socket, domain, type, protocol);
}

static int r80i_bind(int fd, const void *address, unsigned int length)
{
	return (int)my_syscall3(__NR_bind, fd, address, length);
}

static int r80i_listen(int fd, int backlog)
{
	return (int)my_syscall2(__NR_listen, fd, backlog);
}

static int r80i_accept(int fd)
{
	return (int)my_syscall3(__NR_accept, fd, 0, 0);
}

static int r80i_getsockopt(int fd, int level, int option,
			  void *value, unsigned int *length)
{
	return (int)my_syscall5(__NR_getsockopt, fd, level, option,
		value, length);
}

static int r80i_fcntl(int fd, int command, int value)
{
	return (int)my_syscall3(__NR_fcntl, fd, command, value);
}

static void make_mountpoints(void)
{
	(void)mkdir("/dev", 0755);
	(void)mkdir("/proc", 0555);
	(void)mkdir("/sys", 0555);
}

static void make_system_mountpoints(void)
{
	(void)mkdir("/newroot", 0755);
	(void)mkdir("/newroot/dev", 0755);
	(void)mkdir("/newroot/proc", 0555);
	(void)mkdir("/newroot/sys", 0555);
}

static int r80i_trace(const char marker[4])
{
	return write_marker_at(R80I_TRACE_OFFSET, marker);
}

static __attribute__((noreturn)) void r80i_reboot_required(
	const char marker[4], const char *reason)
{
	r80i_state = R80I_REBOOT_REQUIRED;
	if (marker) (void)r80i_trace(marker);
	(void)write_checkpoint("USRE");
	report(reason);
	(void)my_syscall0(__NR_sync);
	(void)reboot(LINUX_REBOOT_CMD_RESTART);
	for (;;)
		(void)sleep(1);
}

static int r80i_mount_system_partition(void)
{
	unsigned int step;

	for (step = 0; step < ROOT_WAIT_STEPS; step++) {
		if (mount("/dev/mmcblk0p1", "/newroot", "ext4",
			  MS_NOATIME, 0) == 0)
			return 0;
		(void)msleep(ROOT_WAIT_MILLISECONDS);
	}
	return -1;
}

static int r80i_bind_mount(const char *source, const char *target)
{
	return mount(source, target, 0, MS_BIND | MS_REC, 0);
}

static int r80i_mount_child_proc(void)
{
	/* A procfs instance records the PID namespace of its mounter.  Binding the
	 * supervisor's procfs would make child-local PIDs impossible to verify. */
	return mount("proc", "/newroot/proc", "proc",
		     MS_NOSUID | MS_NODEV | MS_NOEXEC, 0);
}

static __attribute__((noreturn)) void r80i_run_system_child(void)
{
	char *init_argv[] = { "/sbin/init", 0 };
	char *initial_envp[] = {
		"HOME=/", "PATH=/sbin:/bin:/usr/sbin:/usr/bin", "TERM=linux", 0,
	};
	char *return_envp[] = {
		"HOME=/", "PATH=/sbin:/bin:/usr/sbin:/usr/bin", "TERM=linux",
		"GKD_DEBUG_RETURN=1", 0,
	};
	char **init_envp = r80i_returning ? return_envp : initial_envp;

	if (r80i_listener >= 0)
		(void)close(r80i_listener);
	if (mount(0, "/", 0, MS_REC | MS_PRIVATE, 0) < 0)
		r80i_reboot_required("8M01", "GKD Round80: private system mount namespace failed\n");
	make_system_mountpoints();
	if (r80i_mount_system_partition() < 0)
		r80i_reboot_required("8M02", "GKD Round80: ordinary system P1 mount failed\n");
	if (!r80i_returning && round39_framebuffer_ready) {
		if (framebuffer_external_loop(GKD_ROUND38_ANIMATION_PATH) < 0) {
			report("GKD Round39: external animation invalid; using embedded fallback\n");
			(void)framebuffer_formal_loader();
		}
	}
	(void)write_checkpoint("USR4");
	if (r80i_bind_mount("/dev", "/newroot/dev") < 0 ||
	    r80i_mount_child_proc() < 0 ||
	    r80i_bind_mount("/sys", "/newroot/sys") < 0)
		r80i_reboot_required("8M03", "GKD Round80: ordinary system root setup failed\n");
	(void)write_checkpoint("USR5");
	if (chroot("/newroot") < 0 || chdir("/") < 0)
		r80i_reboot_required("8M04", "GKD Round80: ordinary system chroot failed\n");
	(void)write_checkpoint("USR6");
	(void)write_checkpoint("USR7");
	execve("/sbin/init", init_argv, init_envp);
	r80i_reboot_required("8M05", "GKD Round80: ordinary system init exec failed\n");
}

static pid_t r80i_spawn_system(int returning)
{
	r80i_returning = returning;
	long result = my_syscall5(__NR_clone,
		CLONE_NEWPID | CLONE_NEWNS | SIGCHLD, 0, 0, 0, 0);
	if (result == 0)
		r80i_run_system_child();
	return (pid_t)result;
}

static int r80i_open_listener(void)
{
	struct r80i_sockaddr_un address;
	unsigned int length;
	unsigned int index;
	int fd;

	memset(&address, 0, sizeof(address));
	address.family = R80I_AF_UNIX;
	address.path[0] = 0;
	for (index = 0; index < sizeof(r80i_socket_name) - 1; ++index)
		address.path[index + 1] = r80i_socket_name[index];
	length = (unsigned int)sizeof(address.family) + 1U +
		(unsigned int)sizeof(r80i_socket_name) - 1U;
	fd = r80i_socket(R80I_AF_UNIX, R80I_SOCK_SEQPACKET, 0);
	if (fd < 0 || r80i_bind(fd, &address, length) < 0 ||
	    r80i_listen(fd, R80I_LISTEN_BACKLOG) < 0 ||
	    r80i_fcntl(fd, R80I_F_SETFL, O_NONBLOCK) < 0 ||
	    r80i_fcntl(fd, R80I_F_SETFD, R80I_FD_CLOEXEC) < 0) {
		if (fd >= 0) (void)close(fd);
		return -1;
	}
	return fd;
}

static int r80i_root_packet(int fd, const char *command, unsigned int size)
{
	struct r80i_peercred credential;
	unsigned int credential_length = sizeof(credential);
	char packet[8];
	long received;

	if (!command || !size || size + 1U > sizeof(packet)) return -1;
	memset(&credential, 0, sizeof(credential));
	memset(packet, 0, sizeof(packet));
	if (r80i_getsockopt(fd, R80I_SOL_SOCKET, R80I_SO_PEERCRED,
			     &credential, &credential_length) < 0 ||
	    credential_length != sizeof(credential) || credential.uid != 0)
		return -1;
	/* One byte beyond the only valid packet makes every oversized record fail. */
	received = read(fd, packet, size + 1U);
	if (received != (long)size || memcmp(packet, command, size) != 0)
		return -1;
	return 0;
}

static int r80i_ack_debug(int fd)
{
	static const char ack[] = "OK\n";
	return write(fd, ack, sizeof(ack) - 1) == (long)(sizeof(ack) - 1) ? 0 : -1;
}

/* RETURN is emitted only after the on-device B/A confirmation dialog. */
static int r80i_return_tick(void)
{
	static const char command[] = "RETURN\n";
	int connection = r80i_accept(r80i_listener);
	int accepted = 0;

	if (connection < 0) return 0;
	if (r80i_state == R80I_DEBUG &&
	    r80i_root_packet(connection, command, sizeof(command) - 1U) == 0 &&
	    r80i_ack_debug(connection) == 0)
		accepted = 1;
	(void)close(connection);
	return accepted;
}

static int r80i_wait_system_exit(pid_t system_pid)
{
	unsigned int step;
	int status;
	for (step = 0; step < R80I_SYSTEM_EXIT_STEPS; ++step) {
		pid_t waited = waitpid(system_pid, &status, WNOHANG);
		if (waited == system_pid) return 0;
		if (waited < 0) return -1;
		(void)msleep(100);
	}
	return -1;
}

static int r80i_loop_path(char *path, unsigned int capacity,
			  unsigned int index)
{
	unsigned int used = 0;
	unsigned int length;
	static const char prefix[] = "/dev/loop";

	length = sizeof(prefix) - 1U;
	if (length >= capacity) return -1;
	memcpy(path, prefix, length);
	used = length;
	if (index >= 10U) {
		if (used + 1U >= capacity) return -1;
		path[used++] = (char)('0' + index / 10U);
	}
	if (used + 1U >= capacity) return -1;
	path[used++] = (char)('0' + index % 10U);
	path[used] = 0;
	return 0;
}

static int r80i_release_p2_loops(void)
{
	static const char p2_prefix[] = "/media/data/";
	unsigned int index;

	for (index = 0; index < R80I_LOOP_SCAN_MAX; ++index) {
		char device[32];
		struct r80i_loop_info64 info;
		int fd;

		if (r80i_loop_path(device, sizeof(device), index) < 0)
			return -1;
		fd = open(device, O_RDONLY | O_CLOEXEC | O_NOFOLLOW, 0);
		if (fd < 0) continue;
		memset(&info, 0, sizeof(info));
		if (ioctl(fd, R80I_LOOP_GET_STATUS64, &info) < 0) {
			if (close(fd) < 0) return -1;
			continue;
		}
		info.file_name[sizeof(info.file_name) - 1U] = 0;
		if (strncmp((const char *)info.file_name, p2_prefix,
			    sizeof(p2_prefix) - 1U) != 0) {
			if (close(fd) < 0) return -1;
			continue;
		}
		if (ioctl(fd, R80I_LOOP_CLR_FD, 0) < 0) {
			(void)close(fd);
			return -1;
		}
		memset(&info, 0, sizeof(info));
		if (ioctl(fd, R80I_LOOP_GET_STATUS64, &info) == 0) {
			(void)close(fd);
			return -1;
		}
		if (close(fd) < 0) return -1;
	}
	return 0;
}

static int r80i_runtime_release_verified(void)
{
	/* A successful runtime already observed empty-LUN or exact not-attached,
	 * then tore down ConfigFS.  Recheck every device-side offline invariant. */
	return r64m_gadget_absent() && r64m_mounts_offline() == 0 &&
	       r80_swap_offline() == 0 ? 0 : -1;
}

static int r80i_kernel_slot_hash_fd(int fd,
				    unsigned char output[R64M_SHA256_BYTES])
{
	struct r64m_sha256 hash;
	unsigned char buffer[R64M_COPY_CHUNK];
	unsigned long total = 0;
	if (R64M_LSEEK(fd, R80I_KERNEL_SLOT_OFFSET, SEEK_SET) !=
	    R80I_KERNEL_SLOT_OFFSET) return -1;
	r64m_sha256_init(&hash);
	while (total < R80I_KERNEL_SLOT_BYTES) {
		unsigned long wanted = R80I_KERNEL_SLOT_BYTES - total;
		long count;
		if (wanted > sizeof(buffer)) wanted = sizeof(buffer);
		count = R64M_READ(fd, buffer, wanted);
		if (count != (long)wanted) return -1;
		r64m_sha256_update(&hash, buffer, wanted);
		total += wanted;
	}
	r64m_sha256_final(&hash, output);
	return 0;
}

static int r80i_capture_compatibility(void)
{
	int fd = open(R64M_RAW_DEVICE, O_RDONLY | O_CLOEXEC | O_NOFOLLOW, 0);
	int result = -1;
	(void)my_syscall0(__NR_sync);
	if (fd >= 0 && ioctl(fd, BLKFLSBUF, 0) == 0 &&
	    r64_geometry(fd) == 0 &&
	    r80i_kernel_slot_hash_fd(fd, r80i_kernel_before) == 0) {
		r80i_kernel_before_valid = 1;
		result = 0;
	}
	if (fd >= 0 && close(fd) < 0) result = -1;
	return result;
}

static int r80i_reread_partition_table(void)
{
	int fd = open("/dev/mmcblk0", O_RDONLY | O_CLOEXEC | O_NOFOLLOW, 0);
	int result = -1;

	if (fd >= 0 && ioctl(fd, BLKFLSBUF, 0) == 0 &&
	    ioctl(fd, BLKRRPART, 0) == 0)
		result = 0;
	if (fd >= 0 && close(fd) < 0)
		result = -1;
	return result;
}

static int r80i_layout_and_kernel_slot_compatible(void)
{
	unsigned char current[R64M_SHA256_BYTES];
	int fd = open(R64M_RAW_DEVICE, O_RDONLY | O_CLOEXEC | O_NOFOLLOW, 0);
	int result = -1;
	if (r80i_kernel_before_valid && fd >= 0 && r64_geometry(fd) == 0 &&
	    r80i_kernel_slot_hash_fd(fd, current) == 0 &&
	    r64m_bytes_equal(current, r80i_kernel_before, sizeof(current)))
		result = 0;
	if (fd >= 0 && close(fd) < 0) result = -1;
	r80i_kernel_before_valid = 0;
	memset(r80i_kernel_before, 0, sizeof(r80i_kernel_before));
	return result;
}

static pid_t r80i_debug_cycle(pid_t system_pid)
{
	r80i_state = R80I_QUIESCING;
	(void)r80i_trace("D000");
	if (kill(system_pid, SIGQUIT) < 0 || r80i_wait_system_exit(system_pid) < 0)
		r80i_reboot_required("8D01", "GKD Round80: ordinary system shutdown failed\n");
	(void)r80i_trace("L000");
	if (r80i_release_p2_loops() < 0)
		r80i_reboot_required("8L01", "GKD Round80: P2 loop release failed\n");
	(void)r80i_trace("L100");
	(void)r80i_trace("W000");
	if (r80_swap_offline() < 0) {
		(void)my_syscall1(__NR_swapoff, R80_P3_DEVICE);
		(void)my_syscall0(__NR_sync);
		if (r80_swap_offline() < 0)
			r80i_reboot_required("8W01", "GKD Round80: P3 swapoff failed\n");
	}
	(void)r80i_trace("W100");
	(void)r80i_trace("D100");
	if (r80i_capture_compatibility() < 0)
		r80i_reboot_required("8D02", "GKD Round80: compatibility snapshot failed\n");
	(void)r80i_trace("D200");
	r80i_state = R80I_DEBUG;
	(void)r80i_trace("D300");
	if (r80_debug_runtime(&r64m_final_payload) < 0)
		r80i_reboot_required(0, "GKD Round80: maintenance runtime failed\n");
	(void)r80i_trace("D400");
	r80i_state = R80I_RESTORING;
	if (r80i_runtime_release_verified() < 0 ||
	    r80i_reread_partition_table() < 0 ||
	    r80i_layout_and_kernel_slot_compatible() < 0)
		r80i_reboot_required("8R01", "GKD Round80: restoration compatibility rejected\n");
	system_pid = r80i_spawn_system(1);
	if (system_pid < 0)
		r80i_reboot_required("8R02", "GKD Round80: ordinary system respawn failed\n");
	r80i_state = R80I_SM;
	(void)r80i_trace("D900");
	return system_pid;
}

static pid_t r80i_accept_command(pid_t system_pid)
{
	static const char command[] = "DEBUG\n";
	int connection = r80i_accept(r80i_listener);
	int accepted = 0;

	if (connection < 0)
		return system_pid;
	if (r80i_state == R80I_SM &&
	    r80i_root_packet(connection, command, sizeof(command) - 1U) == 0 &&
	    r80i_ack_debug(connection) == 0)
		accepted = 1;
	(void)close(connection);
	return accepted ? r80i_debug_cycle(system_pid) : system_pid;
}

static __attribute__((noreturn)) void r80i_supervise(pid_t system_pid)
{
	struct pollfd listener_poll;
	int status;

	listener_poll.fd = r80i_listener;
	listener_poll.events = POLLIN;
	for (;;) {
		listener_poll.revents = 0;
		(void)poll(&listener_poll, 1, 100);
		if (listener_poll.revents & POLLIN)
			system_pid = r80i_accept_command(system_pid);
		if (waitpid(system_pid, &status, WNOHANG) == system_pid)
			r80i_reboot_required("8S01", "GKD Round80: ordinary system exited unexpectedly\n");
	}
}

int main(int argc, char **argv, char **envp)
{
	pid_t system_pid;

	(void)argc;
	(void)argv;
	(void)envp;
	report("GKD Round80 permanent RAM supervisor started\n");
	(void)write_checkpoint("USR0");
	make_mountpoints();
	if (mount("devtmpfs", "/dev", "devtmpfs", 0, 0) < 0 ||
	    mkdir("/dev/pts", 0755) < 0 ||
	    mount("devpts", "/dev/pts", "devpts", MS_NOSUID | MS_NOEXEC,
		  "gid=5,mode=620,ptmxmode=000") < 0 ||
	    mount("proc", "/proc", "proc", 0, 0) < 0 ||
	    mount("sysfs", "/sys", "sysfs", 0, 0) < 0)
		r80i_reboot_required("8B01", "GKD Round80: permanent pseudo mounts failed\n");
	(void)write_checkpoint("USR1");
	round39_framebuffer_ready = framebuffer_rgb565_selftest() == 0;
	r80i_listener = r80i_open_listener();
	if (r80i_listener < 0)
		r80i_reboot_required("8B02", "GKD Round80: supervisor socket failed\n");
	system_pid = r80i_spawn_system(0);
	if (system_pid < 0)
		r80i_reboot_required("8B03", "GKD Round80: initial system spawn failed\n");
	r80i_state = R80I_SM;
	r80i_supervise(system_pid);
}
